import{_ as a,c as r,o,a3 as t}from"./chunks/framework.BurWKwwG.js";const m=JSON.parse('{"title":"Browse & Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"3.3_browse.md","filePath":"3.3_browse.md"}'),s={name:"3.3_browse.md"};function i(l,e,n,c,p,d){return o(),r("div",null,e[0]||(e[0]=[t('<h1 id="browse-analysis" tabindex="-1">Browse &amp; Analysis <a class="header-anchor" href="#browse-analysis" aria-label="Permalink to “Browse &amp; Analysis”">​</a></h1><h2 id="biomarker-browser" tabindex="-1">Biomarker Browser <a class="header-anchor" href="#biomarker-browser" aria-label="Permalink to “Biomarker Browser”">​</a></h2><p>The <a href="/biomarkers">Biomarkers</a> page (<code>/biomarkers</code>) provides structured access to curated colorectal cancer biomarker records. Records are displayed in a paginated table with columns covering biomarker name, gene symbol, type, category, cancer stage, experiment method, and more. Use the search bar to filter records by keyword.</p><h2 id="gene-expression-atlas-umap" tabindex="-1">Gene Expression Atlas (UMAP) <a class="header-anchor" href="#gene-expression-atlas-umap" aria-label="Permalink to “Gene Expression Atlas (UMAP)”">​</a></h2><p>The <a href="/umap">UMAP Explorer</a> (<code>/umap</code>) visualizes single-cell RNA-seq data as interactive UMAP plots.</p><ul><li><strong>Dataset Selection</strong>: Choose from available scRNA-seq datasets</li><li><strong>Cell Type Filter</strong>: Filter cells by annotated cell type</li><li><strong>Gene Expression Overlay</strong>: Enter a gene symbol (with autocomplete) to color-code cells by expression level</li><li><strong>Default Loading</strong>: The UMAP plot loads 10,000 cells by default for performance</li></ul><h2 id="network-analysis" tabindex="-1">Network Analysis <a class="header-anchor" href="#network-analysis" aria-label="Permalink to “Network Analysis”">​</a></h2><p>The <a href="/network">Network Analysis</a> page (<code>/network</code>) displays protein-protein interaction (PPI) networks using Cytoscape.js, with data from the STRING database (v12.0).</p><ul><li>Build networks from manual input, CBD database proteins or file upload (12,000+ species)</li><li>Expand networks with high-confidence first-shell partners (instant local index for human)</li><li>Evidence-based edge coloring, module detection (Louvain), enrichment, proximity testing and set comparison</li><li>Export PNG/SVG images, GraphML for Cytoscape desktop, and a full JSON analysis snapshot</li></ul><p>See <a href="./3.5_network.html">Network Analysis</a> for the complete feature guide.</p><h2 id="mamof-framework" tabindex="-1">MAMOF Framework <a class="header-anchor" href="#mamof-framework" aria-label="Permalink to “MAMOF Framework”">​</a></h2><p>The <a href="/mamof">MAMOF Framework</a> page (<code>/mamof</code>) introduces the Multi-Ancestry Multi-Omics Framework - the computational approach behind CBD3 for identifying universal and population-specific colorectal cancer biomarkers, including an illustrated overview of the analysis pipeline.</p><p>The single-cell analysis suite and the clinical analysis pages (survival, immune infiltration) are planned for a future release - see the <a href="./6_update.html">Update &amp; TODO List</a>.</p><h2 id="data-export" tabindex="-1">Data Export <a class="header-anchor" href="#data-export" aria-label="Permalink to “Data Export”">​</a></h2><p>Charts throughout the platform can be exported as images (PNG/SVG) using the built-in ECharts or Cytoscape.js export functionality.</p>',15)]))}const f=a(s,[["render",i]]);export{m as __pageData,f as default};
